// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/agent/v1/logs", wrapper.QueryAgentLogs)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/agent/v1/logs/files", wrapper.ListAgentLogFiles)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/agent/v1/logs/files/{name}", wrapper.DownloadAgentLogFile)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/agent/v1/shutdown", wrapper.ShutdownAgent)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/agent/v1/status", wrapper.GetAgentStatus)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/agent/v1/stop", wrapper.StopTask)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/agent/v1/task", wrapper.AssignTask)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/agent/v1/version", wrapper.GetAgentVersion)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/healthz", wrapper.GetAgentHealth)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/sbot/agent/register", wrapper.RegisterAgent)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/sbot/agent/stress", wrapper.ReportAgentStress)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/sbot/agent/system", wrapper.ReportAgentSystem)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/sbot/agent/{id}/deregister", wrapper.DeregisterAgent)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/sbot/agent/{id}/heartbeat", wrapper.HeartbeatAgent)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/sbot/agent/{id}/pending-task", wrapper.GetPendingAgentTask)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/sbot/agent/{id}/task/{tid}/done", wrapper.CompleteAgentTask)

	return m
}

